input.command:
$roots = @(
  'C:\Users\KickA\Projects\Active\NeuralShell',
  'C:\Users\KickA\Documents\GitHub\NeuralShell',
  'C:\Users\KickA\Projects',
  'C:\Users\KickA\Documents\GitHub',
  "$env:LOCALAPPDATA\Programs\NeuralShell",
  "$env:LOCALAPPDATA\NeuralShell",
  "$env:APPDATA\neuralshell-v5"
)
foreach ($r in $roots) {
  $exists = Test-Path -LiteralPath $r
  $resolved = if ($exists) { (Resolve-Path -LiteralPath $r).Path } else { 'MISSING' }
  $git = if ($exists -and (Test-Path (Join-Path $r '.git'))) {
    try { git -C $r rev-parse --show-toplevel 2>$null } catch { 'no-git' }
  } elseif ($exists) { 'no-.git' } else { 'n/a' }
  Write-Output "--- $r ---"
  Write-Output "  exists=$exists resolved=$resolved gitRoot=$git"
}
# junction check
$active = 'C:\Users\KickA\Projects\Active\NeuralShell'
$gh = 'C:\Users\KickA\Documents\GitHub\NeuralShell'
if ((Test-Path $active) -and (Test-Path $gh)) {
  $a = (Get-Item -LiteralPath $active).Target
  $g = (Get-Item -LiteralPath $gh).Target
  Write-Output "junction Active target: $a"
  Write-Output "junction GH target: $g"
  Write-Output "same resolved: $((Resolve-Path $active).Path -eq (Resolve-Path $gh).Path)"
}

$patterns = @('NeuralShell Setup*.exe','app.asar','dist-renderer','release-output','validation-artifacts')
$searchRoots = @(
  'C:\Users\KickA\Projects',
  'C:\Users\KickA\Documents\GitHub',
  'C:\Users\KickA\Projects\Active\NeuralShell',
  'C:\Users\KickA\Documents\GitHub\NeuralShell',
  "$env:APPDATA\neuralshell-v5"
)
$names = @(
  'NeuralShell Setup*.exe',
  'app.asar',
  'index-*.js',
  'index-*.css'
)
$dirs = @('dist-renderer','release-output','release\final','validation-artifacts','stash')

$results = [System.Collections.Generic.List[object]]::new()

function Add-FileHit($path, $category) {
  if (-not (Test-Path -LiteralPath $path)) { return }
  $item = Get-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue
  if (-not $item) { return }
  $resolved = $item.FullName
  try { $resolved = (Resolve-Path -LiteralPath $path).Path } catch {}
  $hash = $null
  if ($item.Length -lt 500MB) {
    try { $hash = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash } catch { $hash = 'HASH_ERR' }
  } else { $hash = 'TOO_LARGE' }
  $results.Add([pscustomobject]@{
    Category=$category; Path=$resolved; Name=$item.Name
    Size=$item.Length; Modified=$item.LastWriteTimeUtc
    SHA256=$hash
  })
}

foreach ($root in $searchRoots) {
  if (-not (Test-Path -LiteralPath $root)) { continue }
  Write-Host "Scanning $root ..."
  # installers
  Get-ChildItem -LiteralPath $root -Recurse -Filter 'NeuralShell Setup*.exe' -File -ErrorAction SilentlyContinue |
    Where-Object { $_.FullName -notmatch '\\node_modules\\' } |
    ForEach-Object { Add-FileHit $_.FullName 'installer' }
  # app.asar
  Get-ChildItem -LiteralPath $root -Recurse -Filter 'app.asar' -File -ErrorAction SilentlyContinue |
    Where-Object { $_.FullName -notmatch '\\node_modules\\' } |
    ForEach-Object { Add-FileHit $_.FullName 'app.asar' }
  # dist-renderer dirs (marker)
  Get-ChildItem -LiteralPath $root -Recurse -Directory -Filter 'dist-renderer' -ErrorAction SilentlyContinue |
    Where-Object { $_.FullName -notmatch '\\node_modules\\' } |
    ForEach-Object {
      $js = Get-ChildItem -LiteralPath $_.FullName -Filter 'index-*.js' -File -ErrorAction SilentlyContinue | Select-Object -First 1
      if ($js) { Add-FileHit $js.FullName "dist-renderer/index-js" }
      else {
        $results.Add([pscustomobject]@{
          Category='dist-renderer-dir'; Path=(Resolve-Path $_.FullName).Path; Name='dist-renderer'
          Size=0; Modified=$_.LastWriteTimeUtc; SHA256='DIR'
        })
      }
    }
  # release-output dirs
  Get-ChildItem -LiteralPath $root -Recurse -Directory -Filter 'release-output' -ErrorAction SilentlyContinue |
    Where-Object { $_.FullName -notmatch '\\node_modules\\' } |
    ForEach-Object {
      $results.Add([pscustomobject]@{
        Category='release-output-dir'; Path=(Resolve-Path $_.FullName).Path; Name='release-output'
        Size=0; Modified=$_.LastWriteTimeUtc; SHA256='DIR'
      })
    }
  # release/final
  Get-ChildItem -LiteralPath $root -Recurse -Directory -ErrorAction SilentlyContinue |
    Where-Object { $_.Name -eq 'final' -and $_.Parent.Name -eq 'release' } |
    ForEach-Object {
      $results.Add([pscustomobject]@{
        Category='release/final-dir'; Path=(Resolve-Path $_.FullName).Path; Name='release/final'
        Size=0; Modified=$_.LastWriteTimeUtc; SHA256='DIR'
      })
    }
  # validation-artifacts
  Get-ChildItem -LiteralPath $root -Recurse -Directory -Filter 'validation-artifacts' -ErrorAction SilentlyContinue |
    Where-Object { $_.FullName -notmatch '\\node_modules\\' } |
    ForEach-Object {
      $results.Add([pscustomobject]@{
        Category='validation-artifacts'; Path=(Resolve-Path $_.FullName).Path; Name='validation-artifacts'
        Size=0; Modified=$_.LastWriteTimeUtc; SHA256='DIR'
      })
    }
}

# dedupe by SHA256+name for files, path for dirs
$deduped = $results | Sort-Object Modified -Descending | Group-Object {
  if ($_.SHA256 -and $_.SHA256 -notin @('DIR','HASH_ERR','TOO_LARGE')) { "$($_.SHA256)|$($_.Name)" }
  else { $_.Path }
} | ForEach-Object { $_.Group[0] }

$deduped | Sort-Object Modified -Descending | Format-Table Category, Name, Modified, @{N='SizeMB';E={[math]::Round($_.Size/1MB,2)}}, SHA256, Path -AutoSize | Out-String -Width 300
Write-Host "Total unique hits: $($deduped.Count)"

$cutoff = [datetime]'2026-05-02T23:59:59Z'
$markers = @('AdaptiveLayoutEngine','PrimaryWorkspaceRegion','MultiWorkspace','LayoutControlBar','useAdaptiveLayoutChrome','index-CDfqmjqJ')

$candidates = @(
  'C:\Users\KickA\Projects\Active\NeuralShell\dist-renderer',
  'C:\Users\KickA\Projects\Active\NeuralShell\release\final',
  'C:\Users\KickA\Projects\Active\NeuralShell\release-output',
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery',
  'C:\Users\KickA\Projects\Active\NeuralShell-wt-ui-regression\60abd6c\dist-renderer',
  'C:\Users\KickA\Projects\Active\NeuralShell-wt-ui-regression\ea56e79\dist-renderer',
  'C:\Users\KickA\Projects\Active\NeuralShell_clean_push\dist-renderer',
  'C:\Users\KickA\Documents\GitHub\NeuralShell-Proof-Final\dist-renderer',
  'C:\Users\KickA\Documents\GitHub\NeuralShell-Proof-Final-Clean\dist-renderer'
)

function Test-Markers($file) {
  if (-not (Test-Path $file)) { return $null }
  $c = Get-Content -LiteralPath $file -Raw -ErrorAction SilentlyContinue
  if (-not $c) { return $null }
  $found = @()
  foreach ($m in $markers) { if ($c -match [regex]::Escape($m)) { $found += $m } }
  $item = Get-Item -LiteralPath $file
  $hash = (Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash
  [pscustomobject]@{
    File=$file; Bundle=$item.Name; Modified=$item.LastWriteTimeUtc
    AfterMay2=($item.LastWriteTimeUtc -gt $cutoff); SizeKB=[math]::Round($item.Length/1KB,1)
    SHA256=$hash.Substring(0,16)+'...'; Markers=($found -join ', ')
    Score=$found.Count
  }
}

$rows = [System.Collections.Generic.List[object]]::new()
foreach ($dir in $candidates) {
  if (-not (Test-Path $dir)) { continue }
  Get-ChildItem -LiteralPath $dir -Recurse -Include 'index-*.js','index-*.css' -File -ErrorAction SilentlyContinue |
    Where-Object { $_.FullName -match '\\(js|assets)\\index-' } |
    ForEach-Object { $r = Test-Markers $_.FullName; if ($r) { $rows.Add($r) } }
}

# dedupe by hash
$dedup = $rows | Group-Object SHA256 | ForEach-Object { $_.Group | Sort-Object Score -Descending | Select-Object -First 1 }
$dedup | Sort-Object Score -Descending, Modified -Descending |
  Format-Table Bundle, Score, AfterMay2, Modified, SizeKB, Markers, @{N='Dir';E={Split-Path (Split-Path $_.File -Parent) -Parent | Split-Path -Leaf}} -AutoSize | Out-String -Width 250
Write-Host "Unique bundles scanned: $($dedup.Count)"

# Hash key installers/asar (including large ones - may take time)
$files = @(
  'C:\Users\KickA\Projects\Active\NeuralShell\release\final\bin\NeuralShell Setup 2.1.32.exe',
  'C:\Users\KickA\Projects\Active\NeuralShell\release-output\NeuralShell-Windows-x64\NeuralShell\NeuralShell Setup 2.1.29.exe',
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\asar-full-release-232\beta\founder-beta-v2.1.29\installer\NeuralShell Setup 2.1.29.exe',
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\dist-post-revert-20260517-005307\app.asar',
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\unpacked-release-232\resources\app.asar',
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\candidate-release-232-chunked-20260517-010500\js\index-CDfqmjqJ.js'
)
foreach ($f in $files) {
  if (Test-Path -LiteralPath $f) {
    $i = Get-Item -LiteralPath $f
    Write-Host "`n$($i.Name) ($([math]::Round($i.Length/1MB,2)) MB) modified $($i.LastWriteTimeUtc) UTC"
    Write-Host "  path: $f"
    $h = (Get-FileHash -LiteralPath $f -Algorithm SHA256).Hash
    Write-Host "  SHA256: $h"
  } else { Write-Host "MISSING: $f" }
}

$asars = @(
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\unpacked-release-232\resources\app.asar',
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\dist-post-revert-20260517-005307\app.asar',
  'C:\Users\KickA\Projects\Active\NeuralShell\release-output\NeuralShell-Windows-x64\NeuralShell\resources\app.asar'
)
$markers = @('AdaptiveLayoutEngine','PrimaryWorkspaceRegion','MultiWorkspace','LayoutControlBar','useAdaptiveLayoutChrome','index-CDfqmjqJ','index-DRb2Vx79')
foreach ($a in $asars) {
  if (-not (Test-Path $a)) { Write-Host "MISSING $a"; continue }
  $i = Get-Item $a
  Write-Host "`n=== $($i.Name) $($i.LastWriteTimeUtc) ($([math]::Round($i.Length/1MB))MB) ==="
  Write-Host $a
  $bytes = [IO.File]::ReadAllBytes($a)
  $text = [Text.Encoding]::UTF8.GetString($bytes)
  foreach ($m in $markers) {
    if ($text.Contains($m)) { Write-Host "  FOUND: $m" }
  }
}

$installer = 'C:\Users\KickA\Projects\Active\NeuralShell\release\final\bin\NeuralShell Setup 2.1.32.exe'
$markers = @('AdaptiveLayoutEngine','PrimaryWorkspaceRegion','MultiWorkspace','LayoutControlBar','useAdaptiveLayoutChrome','index-CDfqmjqJ','index-DRb2Vx79')
if (Test-Path $installer) {
  $i = Get-Item $installer
  Write-Host "Installer $($i.Name) $($i.LastWriteTimeUtc) $($i.Length) bytes"
  $bytes = [IO.File]::ReadAllBytes($installer)
  $text = [Text.Encoding]::UTF8.GetString($bytes)
  foreach ($m in $markers) { if ($text.Contains($m)) { Write-Host "  FOUND: $m" } else { Write-Host "  absent: $m" } }
}

Get-ChildItem 'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery' -Directory | Sort-Object LastWriteTimeUtc -Descending | ForEach-Object { "$($_.LastWriteTimeUtc.ToString('yyyy-MM-dd HH:mm'))  $($_.Name)" }
Write-Host "`n--- AppData neuralshell-v5 ---"
Get-ChildItem "$env:APPDATA\neuralshell-v5" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 30 FullName, Length, LastWriteTimeUtc

# Scan all candidate folders for full marker set in any .js
$base = 'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery'
$markers = @('AdaptiveLayoutEngine','PrimaryWorkspaceRegion','MultiWorkspace','LayoutControlBar','useAdaptiveLayoutChrome')
$candidateDirs = Get-ChildItem $base -Directory | Where-Object { $_.Name -match 'candidate-|asar-full|stash-extract|unpacked|dist-post' }
foreach ($d in $candidateDirs) {
  $jsFiles = Get-ChildItem $d.FullName -Recurse -Filter '*.js' -File -ErrorAction SilentlyContinue
  if (-not $jsFiles) { continue }
  $allText = ($jsFiles | ForEach-Object { [IO.File]::ReadAllText($_.FullName) }) -join ''
  $found = @(); foreach ($m in $markers) { if ($allText.Contains($m)) { $found += $m } }
  $idx = $jsFiles | Where-Object { $_.Name -match '^index-' } | Select-Object -First 1
  $idxName = if ($idx) { $idx.Name } else { '(no index-*)' }
  [pscustomobject]@{
    Folder=$d.Name; Modified=$d.LastWriteTimeUtc; IndexBundle=$idxName
    MarkerCount=$found.Count; Markers=($found -join ', ')
  }
} | Sort-Object MarkerCount -Descending, Modified -Descending | Format-Table -AutoSize | Out-String -Width 200

$base = 'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery'
$markers = @('AdaptiveLayoutEngine','PrimaryWorkspaceRegion','MultiWorkspace','LayoutControlBar','useAdaptiveLayoutChrome')
$rows = @()
Get-ChildItem $base -Directory | ForEach-Object {
  $d = $_
  $jsFiles = @(Get-ChildItem $d.FullName -Recurse -Filter '*.js' -File -ErrorAction SilentlyContinue)
  if ($jsFiles.Count -eq 0) { return }
  $allText = -join ($jsFiles | ForEach-Object { [IO.File]::ReadAllText($_.FullName) })
  $found = @(); foreach ($m in $markers) { if ($allText.Contains($m)) { $found += $m } }
  $idx = $jsFiles | Where-Object { $_.Name -match '^index-' } | Select-Object -First 1
  $rows += [pscustomobject]@{
    Folder=$d.Name; Modified=$d.LastWriteTimeUtc
    IndexBundle=$(if ($idx) { $idx.Name } else { '-' })
    Score=$found.Count; Markers=($found -join ', ')
  }
}
$rows | Sort-Object Score -Descending | Format-Table -AutoSize

# Find duplicate app.asar by hash (good UI hash only) across Projects+GitHub
$goodHash = '763E5C9D0BE2576F0B5CDF18AD9B5860447BFEA9F2072873124726C901A08124'
$paths = @(
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\unpacked-release-232\resources\app.asar',
  'C:\Users\KickA\Projects\Active\NeuralShell\validation-artifacts\ui-recovery\silent-install-232-20260517\resources\app.asar'
)
foreach ($p in $paths) {
  if (Test-Path $p) {
    $h = (Get-FileHash $p).Hash
    Write-Host "$([IO.Path]::GetFileName((Split-Path (Split-Path $p -Parent) -Parent))) => $h match=$($h -eq $goodHash)"
  }
}
# release-output installer markers
$inst = 'C:\Users\KickA\Projects\Active\NeuralShell\release-output\NeuralShell-Windows-x64\NeuralShell\NeuralShell Setup 2.1.29.exe'
if (Test-Path $inst) {
  $t = [Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes($inst))
  Write-Host "`nrelease-output installer strings:"
  @('AdaptiveLayoutEngine','index-CDfqmjqJ','index-DRb2Vx79') | ForEach-Object { Write-Host "  $_ : $($t.Contains($_))" }
}
